-- Phase M15.1 — Saudi Geographic Master Data Seed
-- Data source attribution:
--   Saudi-Arabia-Regions-Cities-and-Districts by homaily (GPL-2.0)
--   Data collected from the Saudi National Address map.
-- Source repository: https://github.com/homaily/Saudi-Arabia-Regions-Cities-and-Districts
-- Dataset snapshot integrated in this migration: 13 regions, 4,581 city/place records, 3,732 district records.
-- This migration is idempotent and preserves existing KYUM UUIDs and historical relations.

begin;

create extension if not exists pgcrypto;

create table if not exists public.installation_regions(
  id uuid primary key default gen_random_uuid(),
  name text not null unique,
  is_active boolean not null default true,
  created_at timestamptz not null default now()
);
create table if not exists public.installation_cities(
  id uuid primary key default gen_random_uuid(),
  region_id uuid not null references public.installation_regions(id) on delete restrict,
  name text not null,
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  unique(region_id,name)
);
alter table public.installation_neighborhoods add column if not exists region_id uuid references public.installation_regions(id) on delete set null;
alter table public.installation_neighborhoods add column if not exists city_id uuid references public.installation_cities(id) on delete set null;
alter table public.installation_regions add column if not exists national_address_region_id integer;
alter table public.installation_regions add column if not exists name_en text;
alter table public.installation_regions add column if not exists source_code text;
alter table public.installation_cities add column if not exists national_address_city_id bigint;
alter table public.installation_cities add column if not exists name_en text;
alter table public.installation_neighborhoods add column if not exists national_address_district_id bigint;
alter table public.installation_neighborhoods add column if not exists name_en text;

-- The legacy table had a global UNIQUE(name), which cannot represent repeated district names in different cities.
do $$
declare c record;
begin
  for c in
    select conname
    from pg_constraint
    where conrelid='public.installation_neighborhoods'::regclass
      and contype='u'
      and pg_get_constraintdef(oid) ~* '^UNIQUE \(name\)$'
  loop
    execute format('alter table public.installation_neighborhoods drop constraint %I', c.conname);
  end loop;
end $$;

create unique index if not exists uq_installation_regions_national_address_id
  on public.installation_regions(national_address_region_id)
  where national_address_region_id is not null;
create unique index if not exists uq_installation_cities_region_name
  on public.installation_cities(region_id, name);
create index if not exists idx_installation_cities_national_address_id
  on public.installation_cities(national_address_city_id);
create unique index if not exists uq_installation_neighborhoods_city_name
  on public.installation_neighborhoods(city_id, name)
  where city_id is not null;
create unique index if not exists uq_installation_neighborhoods_national_address_id
  on public.installation_neighborhoods(national_address_district_id)
  where national_address_district_id is not null;

create temporary table tmp_sa_regions(
  source_region_id integer primary key,
  code text,
  name_ar text not null,
  name_en text
) on commit drop;
create temporary table tmp_sa_cities(
  source_city_id bigint primary key,
  source_region_id integer not null,
  name_ar text not null,
  name_en text
) on commit drop;
create temporary table tmp_sa_districts(
  source_district_id bigint primary key,
  source_city_id bigint not null,
  source_region_id integer not null,
  name_ar text not null,
  name_en text
) on commit drop;
