-- Regions: preserve existing UUIDs by matching Arabic names, then add missing records.
update public.installation_regions r
set national_address_region_id=s.source_region_id,
    source_code=coalesce(r.source_code,s.code),
    name_en=coalesce(r.name_en,s.name_en),
    is_active=true
from tmp_sa_regions s
where trim(r.name)=trim(s.name_ar);

insert into public.installation_regions(name,national_address_region_id,name_en,source_code,is_active)
select s.name_ar,s.source_region_id,s.name_en,s.code,true
from tmp_sa_regions s
where not exists (
  select 1 from public.installation_regions r
  where r.national_address_region_id=s.source_region_id or trim(r.name)=trim(s.name_ar)
);

-- Cities/places: source contains repeated names inside a region; one logical KYUM city is kept per region/name.
with canonical as (
  select source_region_id,trim(name_ar) name_ar,
         min(source_city_id) source_city_id,
         min(name_en) name_en
  from tmp_sa_cities
  group by source_region_id,trim(name_ar)
)
update public.installation_cities c
set national_address_city_id=coalesce(c.national_address_city_id,x.source_city_id),
    name_en=coalesce(c.name_en,x.name_en),
    is_active=true
from canonical x
join public.installation_regions r on r.national_address_region_id=x.source_region_id
where c.region_id=r.id and trim(c.name)=x.name_ar;

with canonical as (
  select source_region_id,trim(name_ar) name_ar,
         min(source_city_id) source_city_id,
         min(name_en) name_en
  from tmp_sa_cities
  group by source_region_id,trim(name_ar)
)
insert into public.installation_cities(region_id,name,national_address_city_id,name_en,is_active)
select r.id,x.name_ar,x.source_city_id,x.name_en,true
from canonical x
join public.installation_regions r on r.national_address_region_id=x.source_region_id
where not exists (
  select 1 from public.installation_cities c
  where c.region_id=r.id and trim(c.name)=x.name_ar
);

-- Attach legacy neighborhoods to their existing region/city text before importing the master dataset.
update public.installation_neighborhoods n
set region_id=r.id
from public.installation_regions r
where n.region_id is null
  and nullif(trim(n.region),'') is not null
  and trim(r.name)=trim(n.region);
update public.installation_neighborhoods n
set city_id=c.id
from public.installation_cities c
where n.city_id is null
  and n.region_id=c.region_id
  and nullif(trim(n.city),'') is not null
  and trim(c.name)=trim(n.city);

-- Districts: map every source city id through its region/name to the canonical KYUM city.
with mapped as (
  select d.source_district_id,d.name_ar,d.name_en,
         c.id city_uuid,r.id region_uuid,
         row_number() over(partition by c.id,trim(d.name_ar) order by d.source_district_id) rn
  from tmp_sa_districts d
  join tmp_sa_cities sc on sc.source_city_id=d.source_city_id
  join public.installation_regions r on r.national_address_region_id=d.source_region_id
  join public.installation_cities c on c.region_id=r.id and trim(c.name)=trim(sc.name_ar)
)
update public.installation_neighborhoods n
set national_address_district_id=coalesce(n.national_address_district_id,m.source_district_id),
    name_en=coalesce(n.name_en,m.name_en),
    region_id=m.region_uuid,
    city_id=m.city_uuid,
    region=(select name from public.installation_regions where id=m.region_uuid),
    city=(select name from public.installation_cities where id=m.city_uuid),
    is_active=true
from mapped m
where m.rn=1 and n.city_id=m.city_uuid and trim(n.name)=trim(m.name_ar);

with mapped as (
  select d.source_district_id,trim(d.name_ar) name_ar,d.name_en,
         c.id city_uuid,r.id region_uuid,r.name region_name,c.name city_name,
         row_number() over(partition by c.id,trim(d.name_ar) order by d.source_district_id) rn
  from tmp_sa_districts d
  join tmp_sa_cities sc on sc.source_city_id=d.source_city_id
  join public.installation_regions r on r.national_address_region_id=d.source_region_id
  join public.installation_cities c on c.region_id=r.id and trim(c.name)=trim(sc.name_ar)
)
insert into public.installation_neighborhoods(
  name,name_en,region,city,region_id,city_id,national_address_district_id,is_active
)
select m.name_ar,m.name_en,m.region_name,m.city_name,m.region_uuid,m.city_uuid,m.source_district_id,true
from mapped m
where m.rn=1
  and not exists (
    select 1 from public.installation_neighborhoods n
    where n.city_id=m.city_uuid and trim(n.name)=m.name_ar
  );

-- Backfill text fields from relations for consistent legacy UI rendering.
update public.installation_neighborhoods n
set region=r.name, city=c.name
from public.installation_regions r, public.installation_cities c
where n.region_id=r.id and n.city_id=c.id
  and (n.region is distinct from r.name or n.city is distinct from c.name);

analyze public.installation_regions;
analyze public.installation_cities;
analyze public.installation_neighborhoods;

commit;
